    def update_quanty_models(self):
        self.tab_camera.clear()
        self.camera_tabs_list = []
        for i in range(self.spinBox_quanty_cam.value()):
            self.core_ui = QtWidgets.QMainWindow()
            self.tab_model_1 = Ui_ModelTab()
            self.tab_model_1.setupUi(self.core_ui)
            self.camera_tabs_list.append(self.tab_model_1)
            self.tab_camera.addTab(self.core_ui, f'Camera {i+1}')

    def get_data(self):
        data = {}
        for i in range(self.tab_camera.count()):
            camera_tab = self.tab_camera.widget(i)
            camera_name = camera_tab.lineEdit_name_itemcod.text()
            model_data = camera_tab.get_data()
            data[camera_name] = model_data
        return data
    
    def take_data(self):
        return {
            "product_codes": self.lineEdit_name_itemcod.text(),
            "camera_tabs": [form.get_data() for form in self.camera_tabs_list]
        }



    